def find_zero_helper(xs: list, a: float, b: float):
    """
    find_zero_helper finds zero point of a polynomial with coefficients xs
    between a and b.
    """
    if a == b:
        return a
    mid = (a + b) / 2
    if poly(xs, mid) == 0:
        return mid
    if poly(xs, a) * poly(xs, mid) < 0:
        return find_zero_helper(xs, a, mid)
    return find_zero_helper(xs, mid, b)

